(()=>{const A='#ff86c2',INK='#c9b9c9',PAPER='#f2e7ee',reduce=matchMedia('(prefers-reduced-motion:reduce)').matches,b=document.body,s=document.createElement('style');s.textContent=`body{background:radial-gradient(ellipse at 50% 0,#25284d 0,#0d1023 45%,#05060d 100%)}body:before{content:'';position:fixed;inset:0;pointer-events:none;z-index:-2;background:radial-gradient(circle at 18% 28%,#7e8bd518,transparent 28%),radial-gradient(circle at 82% 70%,#ff86c20c,transparent 32%)}.fxbar{position:fixed;top:0;left:0;width:100%;height:2px;background:#fff1;z-index:100}.fxbar i{display:block;height:100%;width:0;background:${A};box-shadow:0 0 15px ${A}}.fx-orb{position:fixed;border-radius:50%;pointer-events:none;filter:blur(100px);opacity:.13;z-index:-1}.fx-orb.a{width:450px;height:450px;left:-180px;top:5%;background:#5365a2;animation:drift 18s ease-in-out infinite}.fx-orb.b{width:400px;height:400px;right:-170px;bottom:5%;background:#d95b9d;animation:drift 22s ease-in-out infinite reverse}.ink-thread{position:fixed;pointer-events:none;z-index:2;width:34px;height:9px;border-bottom:1.5px solid ${INK};border-radius:0 0 70% 35%;opacity:0;filter:blur(.15px);animation:thread 13s ease-in-out infinite}.ink-thread:after{content:'';position:absolute;right:-2px;bottom:-2px;width:4px;height:4px;border-radius:50%;background:${INK};opacity:.55}.ink-speck{position:fixed;pointer-events:none;z-index:2;width:3px;height:3px;border-radius:50%;background:${INK};opacity:0;filter:blur(.3px);animation:speck 8s ease-in-out infinite}.paper-fleck{position:fixed;pointer-events:none;z-index:2;width:5px;height:9px;background:${PAPER};opacity:0;transform:rotate(25deg);filter:blur(.3px);animation:fleck 15s linear infinite}.fx-heart{position:fixed;pointer-events:none;z-index:2;color:${A};opacity:0;filter:drop-shadow(0 0 8px #ff86c244);animation:heart 14s ease-out infinite}.fxr{opacity:0;transform:translateY(38px) scale(.985);transition:1s cubic-bezier(.2,.8,.2,1)}.fxr.on{opacity:1;transform:none}.writing:after{content:'|';animation:cursor .8s steps(1) infinite;color:${A}}.photo-slot.focused{transform:scale(1.025) rotate(-1deg);box-shadow:0 30px 90px #ff4f9d22}.answer-pop{animation:answer .7s ease}@keyframes drift{50%{transform:translate(85px,-50px)}}@keyframes thread{0%{transform:translate3d(-20px,12vh,0) rotate(-18deg) scale(.65);opacity:0}18%{opacity:.14}48%{transform:translate3d(55px,45vh,0) rotate(22deg) scale(1.1);opacity:.1}78%{opacity:.06}100%{transform:translate3d(-15px,88vh,0) rotate(-8deg) scale(.8);opacity:0}}@keyframes speck{0%,100%{transform:translate3d(0,18px,0) scale(.4);opacity:0}30%{opacity:.2}60%{transform:translate3d(24px,-30px,0) scale(1);opacity:.12}80%{opacity:0}}@keyframes fleck{0%{transform:translate3d(0,-8vh,0) rotate(15deg);opacity:0}12%{opacity:.08}55%{transform:translate3d(35px,55vh,0) rotate(130deg);opacity:.05}100%{transform:translate3d(-20px,110vh,0) rotate(240deg);opacity:0}}@keyframes heart{0%{transform:translate3d(0,18vh,0) rotate(-10deg) scale(.65);opacity:0}18%{opacity:.34}100%{transform:translate3d(35px,-105vh,0) rotate(28deg) scale(1);opacity:0}}@keyframes cursor{50%{opacity:0}}@keyframes answer{50%{transform:scale(1.06)}}@media(prefers-reduced-motion:reduce){.ink-thread,.ink-speck,.paper-fleck,.fx-heart{display:none}}`;b.appendChild(s);const bar=document.createElement('div');bar.className='fxbar';bar.innerHTML='<i></i>';b.appendChild(bar);['a','b'].forEach(c=>{const o=document.createElement('div');o.className='fx-orb '+c;b.appendChild(o)});if(!reduce){for(let i=0;i<12;i++){const t=document.createElement('i');t.className='ink-thread';t.style.left=Math.random()*100+'%';t.style.top=5+Math.random()*82+'%';t.style.animationDelay=-Math.random()*13+'s';t.style.animationDuration=10+Math.random()*8+'s';t.style.transformOrigin=Math.random()*100+'% 50%';b.appendChild(t)}for(let i=0;i<22;i++){const p=document.createElement('i');p.className='ink-speck';p.style.left=Math.random()*100+'%';p.style.top=10+Math.random()*85+'%';p.style.animationDelay=-Math.random()*8+'s';p.style.animationDuration=6+Math.random()*6+'s';b.appendChild(p)}for(let i=0;i<9;i++){const f=document.createElement('i');f.className='paper-fleck';f.style.left=Math.random()*100+'%';f.style.animationDelay=-Math.random()*15+'s';f.style.animationDuration=12+Math.random()*8+'s';b.appendChild(f)}for(let i=0;i<7;i++){const h=document.createElement('span');h.className='fx-heart';h.textContent=i%3===0?'♡':'·';h.style.left=8+Math.random()*84+'%';h.style.fontSize=12+Math.random()*12+'px';h.style.animationDelay=-Math.random()*14+'s';h.style.animationDuration=11+Math.random()*8+'s';b.appendChild(h)}}document.querySelectorAll('section').forEach(e=>e.classList.add('fxr'));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('on');io.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.fxr').forEach(e=>io.observe(e));addEventListener('scroll',()=>{const m=document.documentElement.scrollHeight-innerHeight;bar.firstElementChild.style.width=(m?scrollY/m*100:0)+'%'})})();